DROP TABLE IF EXISTS tasks;
DROP TABLE IF EXISTS projects;

CREATE TABLE projects (
  id SERIAL PRIMARY KEY,
  name TEXT NOT NULL UNIQUE
);

CREATE TABLE tasks (
  id SERIAL PRIMARY KEY,
  project_id INT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  priority TEXT NOT NULL CHECK (priority IN ('low', 'medium', 'high')),
  done BOOLEAN NOT NULL DEFAULT false
);

INSERT INTO projects (name) VALUES ('Website'), ('Mobile app'), ('Hiring');

INSERT INTO tasks (project_id, title, priority, done) VALUES
  (1, 'Design homepage', 'high', false),
  (1, 'Write about page', 'low', true),
  (1, 'Fix footer links', 'medium', false),
  (2, 'Set up push notifications', 'high', false),
  (2, 'Login screen', 'medium', true);

import pg from 'pg';

export const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });

// Search tasks by title, case-insensitive. Must be safe for any input.
export async function searchTasks(term) {
  const { rows } = await pool.query(`SELECT * FROM tasks WHERE title ILIKE '%${term}%' ORDER BY id`);
  return rows;
}

// Mark ONE task as done.
export async function completeTask(id) {
  await pool.query('UPDATE tasks SET done = true');
}

// ALL projects with their task counts (including projects with 0 tasks).
export async function projectsWithCounts() {
  const { rows } = await pool.query(`
    SELECT p.name, COUNT(t.id) AS task_count
    FROM projects p
    JOIN tasks t ON t.project_id = p.id
    GROUP BY p.id, p.name
    ORDER BY p.name`);
  return rows;
}

// Number of open (not done) tasks per priority.
export async function openByPriority() {
  const { rows } = await pool.query(`
    SELECT priority, COUNT(*)::int AS open_count
    FROM tasks
    WHERE done = false`);
  return rows;
}

// This one is correct.
export async function openTitles() {
  const { rows } = await pool.query('SELECT title FROM tasks WHERE done = false ORDER BY id');
  return rows.map((r) => r.title);
}

import * as repo from './tasks.repo.js';

console.log('search page:', (await repo.searchTasks('page')).map((t) => t.title));
console.log('search quote:', (await repo.searchTasks("it's")).length);
console.log('counts:', await repo.projectsWithCounts());
console.log('open by priority:', await repo.openByPriority());
await repo.completeTask(1);
console.log('open titles:', await repo.openTitles());
await repo.pool.end();
